# Break My Fix finding 1, generated by Tracefix: _normalize_name_in_topic_msg returns a wrong value.
# Property (issue): For a Shelly 3EM topic shellies/<device>/emeter/<phase>/<metric>, changing only the phase must yield a different normalized topic, so the phases can be told apart. This should hold for any device id, including real ids such as shellyem3-XXXX.
# Quote: there's no way to either sum, or differentiate the three phases' measurements
# Run it with pytest: it fails for as long as the code breaks this property.

import re

from mqtt_exporter.main import _normalize_name_in_topic_msg


def test_break_my_fix_1() -> None:
    topic = 'shellies/living-room-3em/emeter/0/power'
    payload = '10'
    # The property applies to this input: re.fullmatch(r'shellies/[A-Za-z0-9_-]+/emeter/[0-9]+/[a-z_]+', topic) is not None
    result = _normalize_name_in_topic_msg(topic=topic, payload=payload)
    result2 = _normalize_name_in_topic_msg(**{'topic': topic, 'payload': payload, **({"topic": '/'.join(topic.split('/')[:3] + [str(int(topic.split('/')[3]) + 1)] + topic.split('/')[4:])})})
    assert (result[0] != result2[0] and result[1] == result2[1])
